// Command jiragen is the development-time code generator. It reads
// specs/manifest.yaml, validates specifications, overlays and risk metadata,
// and writes Go operation tables under generated/.
//
//	jiragen generate   regenerate generated/ (removes stale generated files)
//	jiragen check      fail if generated/ differs from what would be generated
//	jiragen validate   run the full pipeline without writing; print a summary
//	jiragen update     refresh pinned versions/checksums in the manifest
//	                   (downloads remote specs over HTTPS first)
package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/personal-stack/jira-cli/generator"
)

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}
	fs := flag.NewFlagSet(os.Args[1], flag.ExitOnError)
	root := fs.String("root", ".", "repository root")
	manifest := fs.String("manifest", "specs/manifest.yaml", "manifest path relative to root")
	out := fs.String("out", "generated", "output directory relative to root")
	_ = fs.Parse(os.Args[2:])
	opts := generator.Options{Root: *root, Manifest: *manifest, OutDir: *out}

	var err error
	switch os.Args[1] {
	case "generate":
		err = generate(opts, false)
	case "check":
		err = generate(opts, true)
	case "validate":
		err = validate(opts)
	case "update":
		err = update(opts)
	default:
		usage()
		os.Exit(2)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "jiragen:", err)
		os.Exit(1)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: jiragen generate|check|validate|update [-root .] [-manifest specs/manifest.yaml] [-out generated]")
}

func generate(opts generator.Options, check bool) error {
	res, err := generator.Generate(opts)
	if err != nil {
		return err
	}
	outRoot := filepath.Join(opts.Root, opts.OutDir)
	existing, err := generatedFiles(outRoot)
	if err != nil {
		return err
	}
	var diffs []string
	for name, want := range res.Files {
		p := filepath.Join(opts.Root, filepath.FromSlash(name))
		got, err := os.ReadFile(p)
		if err == nil && bytes.Equal(got, want) {
			continue
		}
		diffs = append(diffs, name)
		if !check {
			if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
				return err
			}
			if err := os.WriteFile(p, want, 0o644); err != nil {
				return err
			}
		}
	}
	for _, p := range existing {
		rel, _ := filepath.Rel(opts.Root, p)
		if _, ok := res.Files[filepath.ToSlash(rel)]; ok {
			continue
		}
		diffs = append(diffs, filepath.ToSlash(rel)+" (stale)")
		if !check {
			if err := os.Remove(p); err != nil {
				return err
			}
		}
	}
	sort.Strings(diffs)
	if check {
		if len(diffs) > 0 {
			return fmt.Errorf("generated code is out of date; run `make generate`:\n  %s", strings.Join(diffs, "\n  "))
		}
		fmt.Println("generated code is up to date")
		return nil
	}
	for _, p := range res.Profiles {
		fmt.Printf("profile %s: %d commands, %d skipped, %d warnings\n", p.Name, len(p.Operations), len(p.Skipped), len(p.Warnings))
	}
	fmt.Printf("%d file(s) changed\n", len(diffs))
	return nil
}

// generatedFiles lists files under dir that carry the generated header, so
// that stale outputs are removed but hand-written files are never touched.
func generatedFiles(dir string) ([]string, error) {
	var out []string
	err := filepath.WalkDir(dir, func(p string, d os.DirEntry, err error) error {
		if errors.Is(err, os.ErrNotExist) {
			return filepath.SkipDir
		}
		if err != nil || d.IsDir() {
			return err
		}
		f, err := os.Open(p)
		if err != nil {
			return err
		}
		head := make([]byte, 64)
		n, _ := io.ReadFull(f, head)
		f.Close()
		if bytes.Contains(head[:n], []byte("Code generated by jiragen. DO NOT EDIT.")) {
			out = append(out, p)
		}
		return nil
	})
	return out, err
}

func validate(opts generator.Options) error {
	res, err := generator.Generate(opts)
	if err != nil {
		return err
	}
	for _, p := range res.Profiles {
		fmt.Printf("profile %s: spec %s %s OK — %d commands, %d skipped, %d warnings\n",
			p.Name, p.Spec.Name, p.Spec.Version, len(p.Operations), len(p.Skipped), len(p.Warnings))
	}
	return nil
}

// update refreshes pinned versions and checksums. It is the only command that
// accepts changed inputs, so a spec change is always an explicit, reviewable
// manifest diff.
func update(opts generator.Options) error {
	mpath := filepath.Join(opts.Root, opts.Manifest)
	m, err := generator.LoadManifest(mpath)
	if err != nil {
		return err
	}
	for pi := range m.Profiles {
		p := &m.Profiles[pi]
		for si := range p.Specs {
			s := &p.Specs[si]
			full := filepath.Join(opts.Root, filepath.FromSlash(s.Path))
			if s.Source == "remote" {
				if err := download(s.URL, full); err != nil {
					return fmt.Errorf("spec %s: %w", s.Name, err)
				}
			}
			b, err := os.ReadFile(full)
			if err != nil {
				return err
			}
			v, err := generator.SpecVersion(b)
			if err != nil {
				return fmt.Errorf("spec %s: %w", s.Name, err)
			}
			s.Version, s.SHA256 = v, sum(b)
		}
		for oi := range p.Overlays {
			b, err := os.ReadFile(filepath.Join(opts.Root, filepath.FromSlash(p.Overlays[oi].Path)))
			if err != nil {
				return err
			}
			p.Overlays[oi].SHA256 = sum(b)
		}
		if p.Risk != nil {
			b, err := os.ReadFile(filepath.Join(opts.Root, filepath.FromSlash(p.Risk.Path)))
			if err != nil {
				return err
			}
			p.Risk.SHA256 = sum(b)
		}
	}
	if err := m.Save(mpath); err != nil {
		return err
	}
	fmt.Println("manifest updated:", mpath)
	return nil
}

func sum(b []byte) string { s := sha256.Sum256(b); return hex.EncodeToString(s[:]) }

func download(url, dest string) error {
	if !strings.HasPrefix(url, "https://") {
		return fmt.Errorf("remote spec URL must use https: %q", url)
	}
	c := &http.Client{Timeout: 2 * time.Minute, CheckRedirect: func(r *http.Request, via []*http.Request) error {
		if r.URL.Scheme != "https" {
			return fmt.Errorf("refusing redirect to non-https URL")
		}
		if len(via) >= 5 {
			return fmt.Errorf("too many redirects")
		}
		return nil
	}}
	resp, err := c.Get(url)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("GET %s: %s", url, resp.Status)
	}
	b, err := io.ReadAll(io.LimitReader(resp.Body, 64<<20+1))
	if err != nil {
		return err
	}
	if len(b) > 64<<20 {
		return fmt.Errorf("remote spec exceeds 64 MiB")
	}
	if _, err := generator.SpecVersion(b); err != nil {
		return fmt.Errorf("downloaded document is not a usable OpenAPI 3 spec: %w", err)
	}
	return os.WriteFile(dest, b, 0o644)
}
